#!/bin/bash
# Generated by scripts/export-killercoda.ts. Passes (exit 0) when the named checks of lab-m08-label-surgery pass.
# Environment overrides, for local tests: SHELF_BIN, KUBECONFIG, SHELF_MARKER_DIR, SHELF_COURSE_DIR, SHELF_LABS_DIR.
LAB=lab-m08-label-surgery
CHECKS="web-name-label web-part-of-label web-third-label web-rolled-out"
MARK="${SHELF_MARKER_DIR:-/tmp}"
SHELF="${SHELF_BIN:-/usr/local/bin/shelf}"
[ -f "$MARK/shelf-failed" ] && { echo "Setup failed: $(cat "$MARK/shelf-failed"). See /tmp/shelf-setup.log." >&2; exit 1; }
[ -f "$MARK/shelf-ready" ] || { echo "Setup is not finished. Wait for RESULT: ready in the first terminal, then click Check again." >&2; exit 1; }
export KUBECONFIG="${KUBECONFIG:-/root/.kube/config}"
cd "${SHELF_COURSE_DIR:-/root/course}" || { echo "The course folder is missing." >&2; exit 1; }
kubectl --context kind-reconcile --request-timeout=10s get nodes >/dev/null 2>&1 || { echo "The cluster is not reachable. Create it first (shelf up), and wait for the node to be Ready." >&2; exit 1; }
# Only this step's checks run, and each wait is capped at 30 s: the lab's own checks.yaml is replaced in a temporary copy of the labs folder.
LABS="${SHELF_LABS_DIR:-${SHELF_COURSE_DIR:-/root/course}/labs}"
T=$(mktemp -d) || { echo "Cannot make a temporary folder." >&2; exit 1; }
trap '[ -n "$T" ] && rm -rf "$T"' EXIT
for e in "$LABS"/*; do n=${e##*/}; [ "$n" = "$LAB" ] || ln -s "$e" "$T/$n"; done
cp -R "$LABS/$LAB" "$T/$LAB"
cat > "$T/$LAB/checks.yaml" <<'KILLERCODA_CHECKS'
apiVersion: labs.reconcile.example/v1
kind: LabChecks
lab: lab-m08-label-surgery
checks:
  - id: web-name-label
    describe: The Pod template of shelf-web has the label app.kubernetes.io/name=shelf-web
    kubectl:
      - get
      - deployment
      - shelf-web
      - -n
      - shelf
      - -o
      - json
    expect:
      jsonpath: "{.spec.template.metadata.labels.app\\.kubernetes\\.io/name}"
      equals: shelf-web
    hint: Labels go under spec.template.metadata.labels, which sets the labels of the Pods. The labels at the top of the Deployment, under metadata, belong to the Deployment itself.
  - id: web-part-of-label
    describe: The Pod template of shelf-web has the label app.kubernetes.io/part-of=shelf
    kubectl:
      - get
      - deployment
      - shelf-web
      - -n
      - shelf
      - -o
      - json
    expect:
      jsonpath: "{.spec.template.metadata.labels.app\\.kubernetes\\.io/part-of}"
      equals: shelf
    hint: "Add `app.kubernetes.io/part-of: shelf` beside the other label in spec.template.metadata.labels."
  - id: web-third-label
    describe: The Pod template of shelf-web has at least one more app.kubernetes.io label, such as component or version
    kubectl:
      - get
      - deployment
      - shelf-web
      - -n
      - shelf
      - -o
      - json
    expect:
      jsonpath: "{.spec.template.metadata.labels}"
      regexCountAtLeast:
        pattern: '"app\.kubernetes\.io/[a-z-]+"'
        count: 3
    hint: "The recommended keys are app.kubernetes.io/name, instance, version, component, part-of and managed-by. Pick one that fits, for example `app.kubernetes.io/component: frontend`."
  - id: web-rolled-out
    describe: Two Pods that carry the recommended labels are Ready, so the change has rolled out
    kubectl:
      - get
      - pods
      - -n
      - shelf
      - -l
      - app.kubernetes.io/name=shelf-web,app.kubernetes.io/part-of=shelf
      - -o
      - json
    expect:
      eventually:
        timeout: 30s
        interval: 3s
        expect:
          jsonpath: "{.items[*].status.containerStatuses[*].ready}"
          regexCountAtLeast:
            pattern: "true"
            count: 2
    hint: Apply the file with `kubectl apply --filename label-surgery/shelf-web.yaml`. Changing the Pod template starts a rolling update, and `kubectl get pods --namespace shelf --show-labels` shows the new Pods with their labels.
KILLERCODA_CHECKS
out=$(SHELF_LABS_DIR="$T" timeout 60 "$SHELF" verify "$LAB" 2>&1); rc=$?
if [ "$rc" -eq 124 ]; then echo "The checks took too long. Wait a few seconds and click Check again." >&2; exit 1; fi
if [ "$rc" -ge 2 ]; then echo "$out" >&2; exit 1; fi
bad=0
for id in $CHECKS; do
  printf '%s\n' "$out" | grep -Eq "^(PASS|SKIP) $id " && continue
  bad=1; printf '%s\n' "$out" | grep -E -A2 "^FAIL $id "
done
[ "$bad" -eq 0 ] || echo "If you just applied a change, it may still be rolling out: wait a few seconds and click Check again." >&2
exit "$bad"
